#!/bin/bash
set -e
cd /home/user

jq -r 'keys_unsorted[]' /home/user/localization/en.json | sort > /home/user/localization/en_keys.txt && jq -r 'keys_unsorted[]' /home/user/localization/fr.json | sort > /home/user/localization/fr_keys.txt && jq -r 'keys_unsorted[]' /home/user/localization/es.json | sort > /home/user/localization/es_keys.txt
python3 -c "import json; print('\n'.join(sorted(json.load(open('/home/user/localization/en.json')).keys())))" > /home/user/localization/en_keys.txt && python3 -c "import json; print('\n'.join(sorted(json.load(open('/home/user/localization/fr.json')).keys())))" > /home/user/localization/fr_keys.txt && python3 -c "import json; print('\n'.join(sorted(json.load(open('/home/user/localization/es.json')).keys())))" > /home/user/localization/es_keys.txt
comm -23 /home/user/localization/en_keys.txt /home/user/localization/fr_keys.txt > /home/user/localization/missing_fr.txt && comm -23 /home/user/localization/en_keys.txt /home/user/localization/es_keys.txt > /home/user/localization/missing_es.txt && comm -13 /home/user/localization/en_keys.txt /home/user/localization/fr_keys.txt > /home/user/localization/extra_fr.txt && comm -13 /home/user/localization/en_keys.txt /home/user/localization/es_keys.txt > /home/user/localization/extra_es.txt
python3 -c "import json; en=json.load(open('/home/user/localization/en.json')); fr=json.load(open('/home/user/localization/fr.json')); missing=[l.strip() for l in open('/home/user/localization/missing_fr.txt') if l.strip()]; extra=[l.strip() for l in open('/home/user/localization/extra_fr.txt') if l.strip()]; [fr.pop(k, None) for k in extra]; fr.update({k: f'[[MISSING_TRANSLATION]]{en[k]}[[MISSING_TRANSLATION]]' for k in missing}); with open('/home/user/localization/fr.json','w') as f: json.dump(dict(sorted(fr.items())), f, ensure_ascii=False, indent=2)"
python3 -c "import json; en=json.load(open('/home/user/localization/en.json')); fr=json.load(open('/home/user/localization/fr.json')); missing=[l.strip() for l in open('/home/user/localization/missing_fr.txt') if l.strip()]; extra=[l.strip() for l in open('/home/user/localization/extra_fr.txt') if l.strip()]; [fr.pop(k, None) for k in extra]; fr.update({k: '[[MISSING_TRANSLATION]]'+en[k]+'[[MISSING_TRANSLATION]]' for k in missing}); f=open('/home/user/localization/fr.json','w'); json.dump(dict(sorted(fr.items())), f, ensure_ascii=False, indent=2); f.close()"
python3 -c "import json; en=json.load(open('/home/user/localization/en.json')); es=json.load(open('/home/user/localization/es.json')); missing=[l.strip() for l in open('/home/user/localization/missing_es.txt') if l.strip()]; extra=[l.strip() for l in open('/home/user/localization/extra_es.txt') if l.strip()]; [es.pop(k, None) for k in extra]; es.update({k: '[[MISSING_TRANSLATION]]'+en[k]+'[[MISSING_TRANSLATION]]' for k in missing}); f=open('/home/user/localization/es.json','w'); json.dump(dict(sorted(es.items())), f, ensure_ascii=False, indent=2); f.close()"
python3 -c "import json; en=json.load(open('/home/user/localization/en.json')); f=open('/home/user/localization/en.json','w'); json.dump(dict(sorted(en.items())), f, ensure_ascii=False, indent=2); f.close()"
python3 -c "log=[]; log.append('Missing keys added');[log.append(f'Added to fr.json: {x.strip()}') for x in open('/home/user/localization/missing_fr.txt') if x.strip()];[log.append(f'Added to es.json: {x.strip()}') for x in open('/home/user/localization/missing_es.txt') if x.strip()];log.append('');log.append('Extra keys removed');[log.append(f'Removed from fr.json: {x.strip()}') for x in open('/home/user/localization/extra_fr.txt') if x.strip()];[log.append(f'Removed from es.json: {x.strip()}') for x in open('/home/user/localization/extra_es.txt') if x.strip()];log.append('');log.append('Final key count');import json; log.append(f\"en.json: {len(json.load(open('/home/user/localization/en.json')))} keys\"); log.append(f\"fr.json: {len(json.load(open('/home/user/localization/fr.json')))} keys\"); log.append(f\"es.json: {len(json.load(open('/home/user/localization/es.json')))} keys\"); open('/home/user/localization/update_report.log','w').write('\n'.join(log))"
cat /home/user/localization/update_report.log
